WITH flagged AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) + INTERVAL 60 DAYS THEN 1 ELSE 0 END AS is_new_session FROM web_events), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT s.id, s.session_id, s.page, s.event_time, s.is_new_session, (SELECT MAX(t2.duration_sec) FROM web_events t2 WHERE t2.session_id = s.session_id) AS max_web_event_duration_sec FROM sessionized s;
